<?php
namespace App\Services;
use App\Models\{ActivityLog,Product,StockIn,StockOpname,StockOut,User};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class StockService { public function incoming(array $data,User $user): StockIn { return DB::transaction(function()use($data,$user){$product=Product::lockForUpdate()->findOrFail($data['product_id']);$product->increment('stock',$data['quantity']);$tx=StockIn::create($data+['user_id'=>$user->id]);$this->log($user,'Barang masuk',"{$product->name}: +{$data['quantity']} stok.");return $tx;}); } public function outgoing(array $data,User $user): StockOut { return DB::transaction(function()use($data,$user){$product=Product::lockForUpdate()->findOrFail($data['product_id']);if($product->stock<$data['quantity'])throw ValidationException::withMessages(['quantity'=>'Stok tidak mencukupi.']);$product->decrement('stock',$data['quantity']);$tx=StockOut::create($data+['user_id'=>$user->id]);$this->log($user,'Barang keluar',"{$product->name}: -{$data['quantity']} stok.");return $tx;}); } public function opname(array $data,User $user): StockOpname { return DB::transaction(function()use($data,$user){$product=Product::lockForUpdate()->findOrFail($data['product_id']);$system=$product->stock;$physical=(int)$data['physical_stock'];$product->update(['stock'=>$physical]);$tx=StockOpname::create($data+['user_id'=>$user->id,'system_stock'=>$system,'difference'=>$physical-$system]);$this->log($user,'Stock opname',"{$product->name}: {$system} menjadi {$physical}.");return $tx;}); } private function log(User $user,string $action,string $description):void{ActivityLog::create(['user_id'=>$user->id,'action'=>$action,'description'=>$description]);} }
